import {clothReadout} from './cloth-diagnostics.js';
import {clothMassControls} from './cloth-mass-editor.js';
import {clothPinControls} from './cloth-pin-editor.js';
import {jointDOFControls} from './joint-dof-editor.js';
import {vehicleReadout} from './vehicle-diagnostics.js';
import {vehiclePowertrainControls} from './vehicle-powertrain-editor.js';
import {abilityReadout} from './ability-inspector.js';
import {animationBudgetReadout} from './animation-budget-inspector.js';
import {vehicleWheelControls} from './vehicle-inspector.js';
import {lightBlendChoices} from './light-blend-styles.js';
import {componentDefinitions,componentDefaults,componentPropertyVisible,physicsBodyCandidates,objectComponents} from './scene-components.js';
import {escapeText as esc} from './scene-editor.js';
import {icon,assetIcon} from './icons.js';
import {geometryControls} from './collision-editor.js';
import {sortingLayerChoices,sortingLayerControls} from './sorting-layers.js';
export function componentInspector(object,files,{running=false,objects=[],sortingLayers}={}){
  return objectComponents(object).filter(c=>c.type!=='Transform').map(component=>{const definition=componentDefinitions[component.type];if(!definition)return '';
    const properties={...componentDefaults(component.type),...component.properties},attrs=key=>`data-scene-component="${esc(component.id)}" data-component-field="${esc(key)}"`,disabled=running?' disabled':'';
    if(['Rigidbody','Rigidbody2D'].includes(component.type)&&properties.isKinematic)properties.bodyType='kinematic';
    const order=['','Main','Emission','Shape','Velocity','Force over Lifetime','Color over Lifetime','Size over Lifetime','Renderer'];let section='';const entries=Object.entries(definition.properties).filter(([key])=>componentPropertyVisible(component.type,key,properties));if(component.type==='ParticleSystem')entries.sort((a,b)=>order.indexOf(a[1].section||'')-order.indexOf(b[1].section||''));const content=entries.map(([key,meta])=>{const value=properties[key],label=esc(meta.label),bounds=`${meta.min===undefined?'':` min="${meta.min}"`}${meta.max===undefined?'':` max="${meta.max}"`} step="${meta.step??.1}"`;let control;
      if(key==='massWeights')return '<div class="component-property vehicle-powertrain-property"><label>'+label+'</label>'+clothMassControls(properties,attrs(key),esc,{disabled:running})+'</div>';if(meta.type==='clothpins'&&running)return '';if(meta.type==='clothpins')return '<div class="component-property vehicle-powertrain-property"><label>'+label+'</label>'+clothPinControls(properties,attrs(key),esc,{disabled:running})+'</div>';if(meta.type==='jointdofs')return jointDOFControls(value,attrs(key),esc,{disabled:running});if(['vehiclegears','vehicletorque'].includes(meta.type))return '<div class="component-property vehicle-powertrain-property"><label>'+label+'</label>'+vehiclePowertrainControls(key,value,attrs(key),esc,{disabled:running})+'</div>';if(meta.type==='vehiclewheels')return vehicleWheelControls(value,attrs(key),esc,{disabled:running});if(meta.type==='json')return '';
      if(['freezePosition','freezeRotation'].includes(key)&&component.type.startsWith('Rigidbody'))control=`<div class="component-axis-lock">${(component.type==='Rigidbody2D'?(key==='freezePosition'?[0,1]:[2]):[0,1,2]).map(axis=>`<label><input type="checkbox" ${value[axis]?'checked':''} ${attrs(key)} data-component-axis="${axis}" aria-label="${label} ${['X','Y','Z'][axis]}"${disabled}>${['X','Y','Z'][axis]}</label>`).join('')}</div>`;
      else if(['vec3','color'].includes(meta.type))control=`<div class="component-vector">${(meta.axes===2?value.slice(0,2):value).map((n,axis)=>component.type==='PhysicsConstraint2D'&&(key.endsWith('Rotation')&&axis!==2||['axis','connectedAxis'].includes(key)&&axis===2)?'':`<label><em>${(meta.type==='color'?['R','G','B','A']:['X','Y','Z'])[axis]}</em><input type="number" value="${n}" ${attrs(key)} data-component-axis="${axis}" ${bounds} aria-label="${label} ${(meta.type==='color'?['R','G','B','A']:['X','Y','Z'])[axis]}"${disabled}></label>`).join('')}</div>`;
      else if(meta.type==='asset')control=`<div class="component-asset"><select ${attrs(key)} data-component-asset="${meta.assetKind}" aria-label="${label}"${disabled}><option value="">없음</option>${files.filter(file=>file.kind===meta.assetKind||(meta.assetKind==='model'&&['mesh','terrain','foliage','lod'].includes(file.kind))||(meta.assetKind==='material'&&file.kind==='materialinstance')||(meta.assetKind==='media'&&file.kind==='audioasset')||(meta.assetKind==='texture'&&file.kind==='sprite'&&!['lightMaskTexture','cookieTexture'].includes(key))||(meta.assetKind==='animation'&&file.kind==='spriteanimation')).map(file=>`<option value="${esc(file.path)}" ${file.path===value?'selected':''}>${esc(file.name.replace(/\.hb[a-z]+\.json$/,''))}</option>`).join('')}${value&&!files.some(f=>f.path===value)?`<option value="${esc(value)}" selected>${esc(value)}</option>`:''}</select>${value?`<button data-open-component-asset="${esc(value)}" aria-label="${label} 열기">${icon('external')}</button>`:''}</div>`;
      else if(meta.componentOf){const target=objects.find(o=>o.id===properties[meta.componentOf]),choices=target?objectComponents(target).filter(c=>c.type===meta.componentType):[];control=`<select ${attrs(key)} aria-label="${label}"${disabled}><option value="${esc(meta.componentType)}">첫 프록시</option>${choices.map(c=>`<option value="${esc(c.id)}" ${c.id===value?'selected':''}>${esc(c.name||c.id)}</option>`).join('')}${value!==meta.componentType&&!choices.some(c=>c.id===value)?`<option value="${esc(value)}" selected>${esc(value)} · 연결 확인 필요</option>`:''}</select>`;}
      else if(meta.objectReference&&meta.type!=='object'){const choices=meta.objectComponent?objects.filter(o=>objectComponents(o).some(c=>c.type===meta.objectComponent)):objects;control=`<select ${attrs(key)} aria-label="${label}"${disabled}><option value="">${esc(meta.emptyLabel||'자동')}</option>${choices.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}${value&&!choices.some(o=>o.id===value)?`<option value="${esc(value)}" selected>${esc(value)} · 연결 확인 필요</option>`:''}</select>`;}
      else if(meta.type==='object'){const choices=physicsBodyCandidates(objects,component.type,object.id);control=`<select ${attrs(key)} aria-label="${label}"${disabled}><option value="">월드에 고정</option>${choices.map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(o.name)}</option>`).join('')}${value&&!choices.some(o=>o.id===value)?`<option value="${esc(value)}" selected>${esc(value)} · 연결 확인 필요</option>`:''}</select>`;}
      else if(['select','sortinglayer'].includes(meta.type))control=`<select ${attrs(key)} aria-label="${label}"${disabled}>${(meta.type==='sortinglayer'?sortingLayerChoices(sortingLayers,value):component.type==='Light2D'&&key==='blendStyle'?lightBlendChoices(objects):meta.choices).map(([id,name])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(name)}</option>`).join('')}</select>`;
      else if(meta.type==='sortinglayers')control=sortingLayerControls(sortingLayers,value,attrs(key),{disabled:running});
      else control=`<input type="${meta.type==='checkbox'?'checkbox':meta.type==='number'?'number':'text'}" ${attrs(key)} ${meta.type==='checkbox'?(value?'checked':''):`value="${esc(value)}"`} ${meta.type==='number'?bounds:'maxlength="200"'} aria-label="${label}"${disabled}>`;
      const heading=meta.section&&section!==meta.section?(section?'</details>':'')+`<details class="component-module" data-component-module="${esc(meta.section)}" ${['Main','Emission','Shape'].includes(meta.section)?'open':''}><summary>${esc(meta.section)}</summary>`:'';section=meta.section||section;return heading+`<div class="component-property" data-property-search="${esc((meta.label+' '+key).toLowerCase())}"><label>${label}</label>${control}</div>`;}).join('');
    return `<details class="component-section scene-component" open data-component-section="${esc(component.id)}"><summary>${icon(definition.icon)}<strong>${esc(definition.label)}</strong><button data-component-menu="${esc(component.id)}" aria-label="${esc(component.name)} 컴포넌트 메뉴">${icon('sliders')}</button></summary>${running&&component.type==='Rope2D'?clothReadout(object.gameplayDebug?.rope,'rope'):''}${running&&component.type==='Cloth'?clothReadout(object.gameplayDebug?.cloth):''}${running&&component.type==='RaycastVehicle'?vehicleReadout(object.gameplayDebug?.vehicle):''}${content}${running&&component.type==='AnimationBudget'?animationBudgetReadout(object.gameplayDebug?.animationBudget):''}${running&&component.type==='AbilitySystem'?abilityReadout(object.gameplayDebug?.ability)+'<div class="ability-set-live"><button data-ability-set-reapply="'+esc(object.id)+'" data-ability-set-asset="'+esc(object.gameplayDebug?.ability?.setAsset||properties.abilitySet||'')+'">세트 재적용</button><label><input type="checkbox" data-ability-set-preserve checked>기본값 유지</label><label><input type="checkbox" data-ability-effects-retain checked>효과 유지</label></div>':''}${section?'</details>':''}${component.type==='MeshRenderer'?'<button data-bake-lightmap="'+esc(object.id)+'"'+disabled+'>간접광 베이크</button>':''}${geometryControls(component.type,properties,esc(component.id),{disabled:running})}</details>`;}).join('')+`<button class="add-component-button" data-action="scene-add-component"${running?' disabled':''}>${icon('plus')} 컴포넌트 추가</button>`;
}
export function componentPicker(hooks){
  const document=hooks.document||globalThis.document;const dialog=document.createElement('dialog');dialog.className='component-picker';dialog.innerHTML='<div class="dialog-heading"><h2>컴포넌트 추가</h2><button data-close aria-label="닫기">'+icon('close')+'</button></div><input type="search" aria-label="컴포넌트 검색" placeholder="컴포넌트 검색"><div class="component-options" role="listbox"></div>';document.body.append(dialog);
  const search=dialog.querySelector('input'),list=dialog.querySelector('.component-options');
  const render=()=>{const q=search.value.toLowerCase();list.innerHTML=Object.entries({...componentDefinitions,...hooks.extra}).filter(([type,d])=>type!=='Transform'&&(type+' '+d.label+' '+d.group).toLowerCase().includes(q)).map(([type,d])=>`<button data-type="${type}" role="option">${icon(d.icon)}<span>${esc(d.label)}<small>${esc(d.group)}</small></span></button>`).join('');};
  search.oninput=render;search.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();list.querySelector('button')?.click();}else if(e.key==='ArrowDown'){e.preventDefault();list.querySelector('button')?.focus();}};
  list.onkeydown=e=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();const buttons=[...list.querySelectorAll('button')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();};
  dialog.onclick=e=>{const button=e.target.closest('button');if(!button)return;if(button.hasAttribute('data-close'))dialog.close();else if(button.dataset.type){try{dialog.close();Promise.resolve(hooks.add(button.dataset.type)).catch(error=>hooks.error(error.message));}catch(error){hooks.error(error.message);}}};dialog.onclose=()=>dialog.remove();render();dialog.showModal();search.focus();
}
